// docs/specs/talent-pool-sheet-sync.md section 2: one full snapshot of one tab.
// n8n does no logic beyond reshaping Google's grid; the app works out what changed.
function buildSnapshot(values, tab) {
  const isFinal = tab === "TEACHING_FINAL";
  const headerIndex = isFinal ? 1 : 0; // Final: row 2 is the header (row 1 is "Last Date Update")
  const headers = (values[headerIndex] || []).map((h) => (h == null ? "" : String(h)));
  const width = headers.length;
  const rows = [];
  for (let i = headerIndex + 1; i < values.length; i++) {
    const raw = values[i] || [];
    // The grid runs on far past the last candidate (NTS reports ~11,700
    // rows); a row with nothing in it is not sent.
    if (raw.every((c) => String(c ?? "").trim() === "")) continue;
    const cells = [];
    for (let j = 0; j < width; j++) cells.push(raw[j] == null ? "" : String(raw[j]));
    rows.push({ row_number: i + 1, cells });
  }
  let sheetLastUpdate = null;
  if (isFinal) {
    const first = values[0] || [];
    const parts = [first[2], first[3]].map((v) => String(v ?? "").trim()).filter(Boolean);
    sheetLastUpdate = parts.length ? parts.join(", ") : null;
  }
  return { source_tab: tab, sheet_last_update: sheetLastUpdate, headers, rows };
}

return [{ json: buildSnapshot($input.first().json.values || [], "TEACHING_FINAL") }];

